/* ============================================
   页面转场动画
   ============================================ */

@keyframes slide-in-right {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}
@keyframes slide-out-right {
  from { transform: translateX(0); }
  to   { transform: translateX(100%); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes slide-up {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}
@keyframes page-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.animate-slide-in-right { animation: slide-in-right 300ms ease-out forwards; }
.animate-slide-out-right { animation: slide-out-right 300ms ease-in forwards; }
.fade-in { animation: fade-in 300ms ease-out forwards; }
.animate-slide-up { animation: slide-up 300ms ease-out forwards; }
.animate-page-in { animation: page-in 150ms ease-out; }

.tf-cg-sheet-root {
  position: absolute;
  left: 0;
  top: 0;
  width: 360px;
  height: 1200px;
  pointer-events: none;
}
.tf-cg-sheet-mask {
  position: absolute;
  inset: 0;
  background-color: var(--color-mask);
  pointer-events: auto;
}
.tf-cg-sheet-container {
  position: absolute;
  left: 0;
  top: 800px;
  width: 360px;
  height: 400px;
  background-color: var(--color-bg-card);
  border-radius: var(--radius-2xl) var(--radius-2xl) 0 0;
  display: flex;
  flex-direction: column;
  pointer-events: auto;
  box-shadow: var(--shadow-lg);
}
.tf-cg-sheet-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-xl) var(--spacing-xl) var(--spacing-lg);
}
.tf-cg-sheet-title {
  color: var(--color-text-primary);
}
.tf-cg-sheet-close {
  background: transparent;
  border: none;
  padding: var(--spacing-xs);
  color: var(--color-text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.tf-cg-sheet-body {
  flex: 1;
  padding: 0 var(--spacing-xl);
  overflow-y: auto;
}
.tf-cg-input-group {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}
.tf-cg-input-label {
  color: var(--color-text-primary);
}
.tf-cg-input {
  width: 100%;
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background-color: var(--color-bg-page);
  color: var(--color-text-primary);
  outline: none;
  box-sizing: border-box;
}
.tf-cg-input::placeholder {
  color: var(--color-text-hint);
}
.tf-cg-sheet-footer {
  padding: var(--spacing-lg) var(--spacing-xl) var(--spacing-2xl);
}
.tf-cg-btn-primary {
  width: 100%;
  padding: var(--spacing-lg) 0;
  background-color: var(--color-primary);
  color: var(--color-text-white);
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  text-align: center;
}

