}

/* ============================================
   页面转场动画
   ============================================ */

@keyframes slide-in-right {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}
@keyframes slide-out-right {
  from { transform: translateX(0); }
  to   { transform: translateX(100%); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes slide-up {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}
@keyframes page-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.animate-slide-in-right { animation: slide-in-right 300ms ease-out forwards; }
.animate-slide-out-right { animation: slide-out-right 300ms ease-in forwards; }
.fade-in { animation: fade-in 300ms ease-out forwards; }
.animate-slide-up { animation: slide-up 300ms ease-out forwards; }
.animate-page-in { animation: page-in 150ms ease-out; }

.tf-cg-sheet-root {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}
.tf-cg-sheet-mask {
  position: absolute;
  inset: 0;
  background-color: var(--color-mask);
}
.tf-cg-sheet-container {
  position: relative;
  width: 100%;
  background-color: var(--color-bg-card);
  border-radius: var(--radius-2xl) var(--radius-2xl) 0 0;
  box-shadow: var(--shadow-lg);
  padding: var(--spacing-xl);
  padding-bottom: calc(var(--spacing-xl) + env(safe-area-inset-bottom));
  z-index: 1;
}
.tf-cg-sheet-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--spacing-xl);
}
.tf-cg-sheet-title {
  color: var(--color-text-primary);
}
.tf-cg-sheet-close {
  background: transparent;
  border: none;
  padding: 0;
  color: var(--color-text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.tf-cg-sheet-body {
  margin-bottom: var(--spacing-2xl);
}
.tf-cg-input-group {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}
.tf-cg-input-label {
  color: var(--color-text-secondary);
}
.tf-cg-input {
  width: 100%;
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background-color: var(--color-bg-card);
  color: var(--color-text-primary);
  outline: none;
}
.tf-cg-input::placeholder {
  color: var(--color-text-hint);
}
.tf-cg-input-disabled {
  background-color: var(--color-bg-disabled);
  color: var(--color-text-disabled);
  cursor: not-allowed;
  border-color: var(--color-border-subtle);
}
.tf-cg-sheet-footer {
  display: flex;
  gap: var(--spacing-lg);
}
.tf-cg-btn-primary {
  flex: 1;
  padding: var(--spacing-lg);
  background-color: var(--color-primary);
  color: var(--color-text-white);
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.tf-cg-btn-loading {
  background-color: var(--color-primary-disabled);
  cursor: not-allowed;
}
.tf-cg-spinner {
  display: inline-block;
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 50%;
  border-top-color: #fff;
  animation: tf-cg-spin 1s ease-in-out infinite;
  margin-right: var(--spacing-md);
}
@keyframes tf-cg-spin {
  to { transform: rotate(360deg); }
}

