}
@keyframes slide-out-right {
  from { transform: translateX(0); }
  to   { transform: translateX(100%); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes slide-up {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}
@keyframes page-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.animate-slide-in-right { animation: slide-in-right 300ms ease-out forwards; }
.animate-slide-out-right { animation: slide-out-right 300ms ease-in forwards; }
.fade-in { animation: fade-in 300ms ease-out forwards; }
.animate-slide-up { animation: slide-up 300ms ease-out forwards; }
.animate-page-in { animation: page-in 150ms ease-out; }

.tf-cg-bottom-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 64px;
  background-color: var(--color-bg-card);
  border-top: 1px solid var(--color-border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--spacing-xl);
  box-sizing: border-box;
  z-index: 100;
}

.tf-cg-bottom-bar__left {
  display: flex;
  align-items: center;
  gap: var(--spacing-2xl);
}

.tf-cg-bottom-bar__action {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  background: none;
  border: none;
  padding: 0;
  color: var(--color-text-primary);
  font-size: var(--font-body-12);
  line-height: var(--line-height-16);
  cursor: pointer;
}

.tf-cg-bottom-bar__action svg {
  width: 24px;
  height: 24px;
  color: var(--color-text-primary);
}

.tf-cg-bottom-bar__right {
  flex: 1;
  display: flex;
  justify-content: flex-end;
  margin-left: var(--spacing-xl);
}

.tf-cg-bottom-bar__primary {
  background-color: var(--color-primary);
  color: var(--color-text-white);
  border: none;
  border-radius: var(--radius-full);
  padding: 10px 32px;
  font-size: var(--font-headline-16);
  line-height: var(--line-height-20);
  font-weight: var(--font-weight-medium);
  cursor: pointer;
  min-width: 120px;
  text-align: center;
}
